const rl = require("readline").createInterface({ input: process.stdin });
var iter = rl[Symbol.asyncIterator]();
const readline = async () => (await iter.next()).value;

void (async function () {
  // 可能有多组测试数据
  while (true) {
    try {
      const [l1, l2] = (await readline()).split(" ").map(Number);

      const A = (await readline()).split(" ").map(Number);
      const B = (await readline()).split(" ").map(Number);

      let sumA = 0;
      for (let a of A) {
        sumA += a;
      }

      let sumB = 0;
      const setB = new Set();

      for (let b of B) {
        sumB += b;
        setB.add(b);
      }

      // 由于本题必然存在解，因此sumA-sumB的结果肯定可以整除2，如果不能整除则half_diff为小数，
      // 而half_diff = a - b，其中a,b都是整数，因此不可能存在half_diff是小数的情况
      const half_diff = (sumA - sumB) / 2;

      // 记录用于交换的最小的a
      let minA = Infinity;
      // 记录题解
      let ans = "";

      for (let a of A) {
        const b = a - half_diff;

        if (setB.has(b)) {
          if (a < minA) {
            minA = a;
            ans = `${a} ${b}`;
          }
        }
      }

      console.log(ans);
    } catch (e) {
      break;
    }
  }
})();

