#include <stdio.h>
#include <limits.h>
#include <string.h>

#define MAX_SIZE 10000
#define MAX_VALUE 100000

int main() {
    // 可能有多组测试数据
    while(1) {
        int l1, l2;
        int res = scanf("%d %d", &l1, &l2);
        if(res != 2) {
            break;
        }

        int A[MAX_SIZE];
        int A_size = 0;

        int sumA = 0;

        while (scanf("%d", &A[A_size])) {
            sumA += A[A_size];
            A_size++;
            if(getchar() != ' ') break;
        }

        int B[MAX_SIZE];
        int B_size = 0;

        int sumB = 0;
        int setB[MAX_VALUE + 1] = {0};

        while (scanf("%d", &B[B_size])) {
            sumB += B[B_size];
            setB[B[B_size]] = 1;
            B_size++;
            if(getchar() != ' ') break;
        }

        // 由于本题必然存在解，因此sumA-sumB的结果肯定可以整除2，如果不能整除则half_diff为小数，
        // 而half_diff = a - b，其中a,b都是整数，因此不可能存在half_diff是小数的情况
        int half_diff = (sumA - sumB) / 2;

        int minA = INT_MAX;
        char ans[15];

        for(int i=0; i<A_size; i++) {
            int a = A[i];
            int b = a - half_diff;
            if(b > 0 && setB[b] && a < minA) {
                minA = a;
                char tmp[15];
                sprintf(tmp, "%d %d", a, b);
                strcpy(ans, tmp);
            }
        }

        puts(ans);
    }

    return 0;
}
